#include <stdio.h>

int main(void) {
    int n = 0;
    if (scanf("%d", &n) != 1) {
        return 1;
    }

    int total = 0;
    for (int i = 0; i < n; i++) {
        int x = 0;
        if (scanf("%d", &x) != 1) {
            return 1;
        }
        total = total + x;
    }

    printf("今天一共 %d 条喵\n", total);

    if (total >= 100) {
        printf("够一百条啦，打完折只收 %d 条喵\n", total * 8 / 10);
    } else {
        printf("还差一点，照旧收 %d 条喵\n", total);
    }

    return 0;
}
